import math


class DataStatistics4:
    TWO = 2
    THREE = 3
    FOUR = 4
    ONE = 1
    HALF = 0.5
    TWO_PI_SQRT = math.sqrt(2 * math.pi)
    TWO_SQRT_PI = 2.0 * math.pi

    @staticmethod
    def mean(data):
        """Calculate the mean of the data."""
        if not data:
            return 0
        return sum(data) / len(data)

    @staticmethod
    def variance(data, mean_value=None):
        """Calculate the population variance of the data."""
        if not data:
            return 0
        if mean_value is None:
            mean_value = DataStatistics4.mean(data)
        n = len(data)
        return sum((x - mean_value) ** 2 for x in data) / n

    @staticmethod
    def standard_deviation(data, mean_value=None):
        """Calculate the population standard deviation of the data."""
        var = DataStatistics4.variance(data, mean_value)
        return math.sqrt(var)

    @staticmethod
    def correlation_coefficient(data1, data2):
        n = len(data1)
        if n == 0 or len(data2) != n:
            return 0

        mean1 = DataStatistics4.mean(data1)
        mean2 = DataStatistics4.mean(data2)

        numerator = sum((data1[i] - mean1) * (data2[i] - mean2) for i in range(n))
        std_dev1 = DataStatistics4.standard_deviation(data1, mean1)
        std_dev2 = DataStatistics4.standard_deviation(data2, mean2)
        denominator = n * std_dev1 * std_dev2

        return numerator / denominator if denominator != 0 else 0

    @staticmethod
    def skewness(data):
        n = len(data)
        if n < 3:
            return 0

        mean = DataStatistics4.mean(data)
        std_dev = DataStatistics4.standard_deviation(data, mean)

        if std_dev == 0:
            return 0

        sum_cubed_deviations = sum((x - mean) ** 3 for x in data)
        skewness = sum_cubed_deviations * n / ((n - 1) * (n - 2) * std_dev ** DataStatistics4.THREE)

        return skewness

    @staticmethod
    def kurtosis(data):
        n = len(data)
        if n == 0:
            return math.nan

        mean = DataStatistics4.mean(data)
        std_dev = DataStatistics4.standard_deviation(data, mean)

        if std_dev == 0:
            return math.nan

        fourth_moment = sum((x - mean) ** DataStatistics4.FOUR for x in data) / n
        kurtosis_value = (fourth_moment / std_dev ** DataStatistics4.FOUR) - DataStatistics4.THREE

        return kurtosis_value

    @staticmethod
    def pdf(data, mu, sigma):
        if sigma == 0:
            return [0.0] * len(data)
        normalization = 1 / (sigma * math.sqrt(DataStatistics4.TWO_PI_SQRT))
        pdf_values = [
            normalization * math.exp(-DataStatistics4.HALF * ((x - mu) / sigma) ** DataStatistics4.TWO)
            for x in data
        ]
        return pdf_values
